@RequiresPermissions("/extra/api/v1/orders/1/temporaryStorage")
    @ApiOperation("暂存接口")
    @PutMapping("/{orderNo}")
    public GenericRpcResponse<Boolean> temporaryStorage(@PathVariable String orderNo,
                                                        @RequestBody @Valid OrderVO orderVO,
                                                        @CurrentSessionContext SessionContext sessionContext) {
        try {
            orderVO.setOrderNo(orderNo);
            orderVO.setInputDate(DateUtil.now());
            extraOrderService.temporaryStorage(orderVO, generateEndorseProposer(sessionContext));
            return GenericRpcResponse.success(true);
        } catch (ExtraOrderException e){
            log.error("订单暂存失败，orderNo:{}",orderNo);
            throw new ExtraOrderException(e.getErrorMessage());
        } catch (Exception e) {
            log.error("订单暂存失败，orderNo:{},错误信息:{}", orderNo, e);
            throw new ExtraOrderException(ExtraErrorEnum.TEMPORARY_FAIL);
        }
    }

public static void error(String format, Object... args) {
        if (Level.ERROR_INT >= logLevel) {
            log.error(format, args);
        }
    }

@RequestMapping(CommonConstant.ERROR_CONTROLLER)
    public void error(HttpServletRequest request) throws Exception {
        throw (Exception) request.getAttribute("filter.error");
    }

public void setOrderNo(String orderNo) {
